SELECT jsonb_build_object('captured_at',statement_timestamp(),'indexes',(SELECT jsonb_agg(jsonb_build_object('name',c.relname,'definition',pg_get_indexdef(i.indexrelid)) ORDER BY c.relname) FROM pg_index i JOIN pg_class c ON c.oid=i.indexrelid JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relname IN ('idx_exercise_attempts_date','idx_exercise_attempts_exercise','idx_exercise_attempts_user_correct','idx_exercises_chapter','idx_exercises_difficulty','idx_friend_requests_users','idx_friends_participants','idx_user_progress_user_chapter')),'columns',(SELECT jsonb_agg(jsonb_build_object('table',c.relname,'name',a.attname,'type',format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'default',pg_get_expr(d.adbin,d.adrelid),'sequence',pg_get_serial_sequence('public.'||c.relname,a.attname)) ORDER BY c.relname,a.attnum) FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE n.nspname='public' AND a.attnum>0 AND NOT a.attisdropped AND ((c.relname='exercise_attempts' AND a.attname IN ('id','created_at')) OR (c.relname='exercises' AND a.attname IN ('id','title','created_at')) OR (c.relname='profiles' AND a.attname IN ('current_streak','max_streak','role','has_seen_tutorial')) OR (c.relname='competences' AND a.attname IN ('chapter_id','max_points'))))) AS metadata;
